class Encrypter {
    private Map<Character, String> enc;
    private Map<String, Integer> cnt;

    public Encrypter(char[] keys, String[] values, String[] dictionary) {
        enc = new HashMap<>();
        cnt = new HashMap<>();
        for (int i = 0; i < keys.length; i++) enc.put(keys[i], values[i]);
        for (String w : dictionary) cnt.merge(encrypt(w), 1, Integer::sum);
    }

    public String encrypt(String word1) {
        StringBuilder sb = new StringBuilder();
        for (char c : word1.toCharArray()) {
            String v = enc.get(c);
            if (v == null) return "";
            sb.append(v);
        }
        return sb.toString();
    }

    public int decrypt(String word2) {
        return cnt.getOrDefault(word2, 0);
    }
};

